go

-- Comprueba los registros cargados en cada tabla:
select 'Membresia' as Tabla, count(*) as Cantidad from Membresia;
select 'Especialidad' as Tabla, count(*) as Cantidad from Especialidad;
select 'Entrenador' as Tabla, count(*) as Cantidad from Entrenador;
select 'EntrenadorEspecialidad' as Tabla, count(*) as Cantidad from EntrenadorEspecialidad;
select 'Clase' as Tabla, count(*) as Cantidad from Clase;
select 'Socio' as Tabla, count(*) as Cantidad from Socio;
select 'Pago' as Tabla, count(*) as Cantidad from Pago;
select 'SesionClase' as Tabla, count(*) as Cantidad from SesionClase;
select 'Reserva' as Tabla, count(*) as Cantidad from Reserva;
